const CREDITS=[["basil", "Przemek P", "CC BY-SA 3.0", "Ocimum_basilicum_for_home_growing.jpg"], ["loaf", "Nleamy (en.wikipedia)", "CC BY 2.5", "Sourdoughbreadcrumb.jpg"], ["trail", "Krzysztof Golik", "CC BY-SA 4.0", "Hiking_path_in_Tolmin_(11).jpg"], ["bed", "maxronnersjo", "CC BY-SA 3.0", "Unmade_bed.jpg"], ["cassette", "fancycrave1 (Pixabay)", "CC0", "Tokyo_Flipper_3_Band_Radio_%C2%B7_Cassette_Tape_Recorder_(2015-06-28_by_fancycrave1)_Radio-821602.jpg"], ["coffees", "Santeri Viinamäki", "CC BY-SA 4.0", "Empty_coffee_cups_20170602.jpg"], ["sunset", "Maksim Sokolov", "CC BY-SA 4.0", "Sunset_on_Lake_Ontario.jpg"], ["boxes", "Roman Eisele", "CC BY-SA 4.0", "Europ%C3%A4isch-Kurzhaar-Kater_Nikita_2013-12-17_auf_Stapel_aus_Umzugskartons.jpg"], ["pizza", "Janine (Flickr)", "CC BY 2.0", "Pizza_with_pineapple.jpg"], ["laptop", "Free-Photos (Pixabay)", "CC0", "Home-office-336377.jpg"], ["creek", "Jakub Fryš", "CC BY-SA 4.0", "Three_Sisters_from_Police_Creek.jpg"], ["fog", "Berit (Flickr)", "CC BY 2.0", "Trees_if_fog_(7266024212).jpg"], ["night", "Pinakpani", "CC BY-SA 4.0", "Bangalore_city_at_night_01.jpg"]];
const BODY_IMG=['basil','loaf','trail','bed','cassette','coffees','sunset','boxes','pizza','laptop'];
const R1_IMG=['creek','trail','fog','sunset','night','creek','trail','night','night','creek'];
function media(k){return '<img class="fc-media" src="'+IMG[k]+'" alt="'+ALT[k]+'" data-art="legal-photo: Wikimedia Commons, see About the photos" loading="lazy" decoding="async">';}
function r1img(body){var i=R1_POSTS.indexOf(body);return i<0?(body.indexOf('opened the app')===0?'bed':'night'):R1_IMG[i];}

const SCREENS=['hire','train','rank','flip-seat','about'];
let aboutBack='hire';
function openAbout(from){
  aboutBack=from;
  const ul=document.getElementById('aboutList');
  if(!ul.childElementCount){
    ul.innerHTML=CREDITS.map(function(c){
      return '<li><img src="'+IMG[c[0]]+'" alt=""><span><b>'+ALT[c[0]]+'</b><br>'+c[1]+' &middot; '+c[2]+'<br><a href="https://commons.wikimedia.org/wiki/File:'+c[3]+'">Wikimedia Commons page</a></span></li>';
    }).join('');
  }
  go('about');
}
